.ride-summary__substat {
  flex: 0 0 auto;
  white-space: nowrap;
}

.ride-summary__substat-metric {
  display: inline-block;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.ride-summary__substat:not(:last-child)::after {
